# Ogni esercizio grande è un progetto di 8 mini esercizi; ogni mini esercizio ha la sua teoria
# (spiega + esempio + errore comune), le istruzioni "Come si fa" e un controllo.
# Sostituisce i 5 esercizi Basi brevi (b1-b5) con 2 esercizi grandi (base1, base2) dentro missioni.json.
import json, copy
P = "src/data/app/seo-pro/missioni.json"
d = json.load(open(P, encoding="utf-8"))
L = '<a href="{}">{}</a>'; B = "/app/percorsi/seo/strumenti/"; PAN = "/app/percorsi/seo/pannello/"

def opz(*xs):
    return [{"id": f"o{i+1}", "testo": t, "giusta": g, "nota": n} for i, (g, t, n) in enumerate(xs)]
def scelta(strumento, domanda, spiega, esempio, errore, come, opzioni, perche, aiuto, dove="", pagina=None, tipo="radio"):
    p = {"strumento": strumento, "tipo": tipo, "domanda": domanda, "spiega": spiega, "esempio": esempio, "errore": errore,
         "compito": "", "come": come, "opzioni": opzioni, "perche": perche, "aiuto": aiuto, "dove": dove}
    if pagina: p["pagina"] = pagina
    return p
def azione(verifica, vai, domanda, spiega, esempio, errore, come, perche, aiuto, dove=""):
    return {"strumento": "pannello", "tipo": "azione", "verifica": verifica, "vai": vai, "domanda": domanda, "spiega": spiega,
            "esempio": esempio, "errore": errore, "compito": "", "come": come, "opzioni": [], "perche": perche, "aiuto": aiuto, "dove": dove}

